-- Controls catalog + per-assessment tracking
CREATE TYPE public.control_status AS ENUM ('not_started','in_progress','implemented','not_required');

CREATE TABLE public.controls (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  key text NOT NULL UNIQUE,
  framework text NOT NULL,
  ref text NOT NULL,
  title text NOT NULL,
  category text,
  description text,
  mappings jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX controls_framework_ref_idx ON public.controls(framework, ref);

GRANT SELECT ON public.controls TO authenticated;
GRANT ALL ON public.controls TO service_role;
ALTER TABLE public.controls ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read controls" ON public.controls FOR SELECT TO authenticated USING (true);

CREATE TABLE public.assessment_controls (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  assessment_id uuid NOT NULL REFERENCES public.assessments(id) ON DELETE CASCADE,
  control_id uuid NOT NULL REFERENCES public.controls(id) ON DELETE CASCADE,
  status public.control_status NOT NULL DEFAULT 'not_started',
  implemented_at date,
  target_date date,
  owner text,
  reason text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (assessment_id, control_id)
);
CREATE INDEX assessment_controls_assessment_idx ON public.assessment_controls(assessment_id);

GRANT SELECT, INSERT, UPDATE, DELETE ON public.assessment_controls TO authenticated;
GRANT ALL ON public.assessment_controls TO service_role;
ALTER TABLE public.assessment_controls ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own assessment controls" ON public.assessment_controls FOR ALL TO authenticated
  USING (EXISTS (SELECT 1 FROM public.assessments a WHERE a.id = assessment_controls.assessment_id AND a.owner_id = auth.uid()))
  WITH CHECK (EXISTS (SELECT 1 FROM public.assessments a WHERE a.id = assessment_controls.assessment_id AND a.owner_id = auth.uid()));

CREATE TRIGGER tg_assessment_controls_updated_at BEFORE UPDATE ON public.assessment_controls
FOR EACH ROW EXECUTE FUNCTION public.tg_touch_updated_at();

